import java.util.*;

class Solution {
  public int minBuildTime(int[] blocks, int split) {
    // Huffman-like: repeatedly pair the two quickest blocks under one split
    PriorityQueue<Integer> pq = new PriorityQueue<>();
    for (int b : blocks) pq.add(b);
    while (pq.size() > 1) {
      pq.poll();
      pq.add(pq.poll() + split);
    }
    return pq.peek();
  }
}
